 static class Slide{String title;List<String> lines=new ArrayList<>();Slide(String t){title=t;}}
 static String xml(String text){StringBuilder b=new StringBuilder();text.codePoints().filter(c->c==9||c==10||c==13||c>=32&&c<=0xD7FF||c>=0xE000&&c<=0xFFFD||c>=0x10000&&c<=0x10FFFF).forEach(b::appendCodePoint);return b.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static List<String> wrap(String line){List<String> out=new ArrayList<>();StringBuilder b=new StringBuilder();int weight=0;for(int cp:line.codePoints().toArray()){int w=cp>255?2:1;if(weight+w>58){out.add(b.toString());b.setLength(0);weight=0;}b.appendCodePoint(cp);weight+=w;}if(b.length()>0)out.add(b.toString());return out;}
 static List<Slide> parse(String text)throws IOException{if(text==null||text.trim().isEmpty())throw new IOException("回答为空，无法生成PPT");if(text.length()>60000)throw new IOException("内容过长，请分成多份PPT");List<Slide> slides=new ArrayList<>();Slide current=new Slide("演示文稿");boolean code=false;for(String raw:text.replace("\r","").split("\n")){String line=raw.trim();if(line.startsWith("```")){code=!code;continue;}if(line.isEmpty())continue;if(!code&&line.matches("#{1,3}\\s+.*")){if(!current.lines.isEmpty())slides.add(current);String title=line.replaceFirst("^#{1,3}\\s+","").replace("**","");current=new Slide(title.length()>42?title.substring(0,42)+"…":title);if(title.length()>42)current.lines.addAll(wrap(title));continue;}if(!code&&line.matches("[-*_]{3,}")){if(!current.lines.isEmpty())slides.add(current);current=new Slide("继续");continue;}line=line.replace("**","").replaceFirst("^[-*]\\s+","• ");for(String part:wrap(line)){if(current.lines.size()>=10){slides.add(current);current=new Slide(current.title.replace("（续）","")+"（续）");}current.lines.add(part);}}if(!current.lines.isEmpty()||slides.isEmpty())slides.add(current);if(slides.size()>80)throw new IOException("超过80页，请缩短内容");return slides;}
 static void put(ZipOutputStream z,String name,String text)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>"+text).getBytes(StandardCharsets.UTF_8));z.closeEntry();}
