 static String root(String tag){return "<p:"+tag+" xmlns:p=\""+P+"\" xmlns:a=\""+A+"\" xmlns:r=\""+R+"\"";}
 public static void write(String text,OutputStream out)throws IOException{List<Slide> slides=parse(text);try(ZipOutputStream z=new ZipOutputStream(out)){StringBuilder types=new StringBuilder("<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/>");String[][] parts={{"/ppt/presentation.xml","presentation"},{"/ppt/slideMasters/slideMaster1.xml","slideMaster"},{"/ppt/slideLayouts/slideLayout1.xml","slideLayout"}};for(String[] part:parts)types.append("<Override PartName=\"").append(part[0]).append("\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.").append(part[1].equals("presentation")?"presentation.main":part[1]).append("+xml\"/>");types.append("<Override PartName=\"/ppt/theme/theme1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.theme+xml\"/>");StringBuilder ids=new StringBuilder(),relationships=new StringBuilder(rel("master","slideMaster","slideMasters/slideMaster1.xml"));
  for(int i=0;i<slides.size();i++){int n=i+1;types.append("<Override PartName=\"/ppt/slides/slide").append(n).append(".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.slide+xml\"/>");ids.append("<p:sldId id=\"").append(256+i).append("\" r:id=\"slide").append(n).append("\"/>");relationships.append(rel("slide"+n,"slide","slides/slide"+n+".xml"));Slide slide=slides.get(i);put(z,"ppt/slides/slide"+n+".xml",root("sld")+"><p:cSld><p:bg><p:bgPr><a:solidFill><a:srgbClr val=\"101D35\"/></a:solidFill><a:effectLst/></p:bgPr></p:bg><p:spTree>"+GROUP+shape(2,"标题",Arrays.asList(slide.title),600000,350000,10900000,1100000,3200,"E7C681")+shape(3,"正文",slide.lines,600000,1600000,10900000,4700000,2400,"F4F0E8")+shape(4,"页码",Arrays.asList(n+" / "+slides.size()),11000000,6400000,800000,300000,1200,"B4C5E1")+"</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>");put(z,"ppt/slides/_rels/slide"+n+".xml.rels",rels(rel("layout","slideLayout","../slideLayouts/slideLayout1.xml")));}
  put(z,"[Content_Types].xml",types+"</Types>");put(z,"_rels/.rels",rels(rel("presentation","officeDocument","ppt/presentation.xml")));put(z,"ppt/presentation.xml",root("presentation")+"><p:sldMasterIdLst><p:sldMasterId id=\"2147483648\" r:id=\"master\"/></p:sldMasterIdLst><p:sldIdLst>"+ids+"</p:sldIdLst><p:sldSz cx=\"12192000\" cy=\"6858000\" type=\"screen16x9\"/><p:notesSz cx=\"6858000\" cy=\"9144000\"/></p:presentation>");put(z,"ppt/_rels/presentation.xml.rels",rels(relationships.toString()));
  put(z,"ppt/slideMasters/slideMaster1.xml",root("sldMaster")+"><p:cSld><p:spTree>"+GROUP+"</p:spTree></p:cSld><p:clrMap accent1=\"accent1\" accent2=\"accent2\" accent3=\"accent3\" accent4=\"accent4\" accent5=\"accent5\" accent6=\"accent6\" bg1=\"lt1\" bg2=\"lt2\" folHlink=\"folHlink\" hlink=\"hlink\" tx1=\"dk1\" tx2=\"dk2\"/><p:sldLayoutIdLst><p:sldLayoutId id=\"2147483649\" r:id=\"layout\"/></p:sldLayoutIdLst><p:txStyles><p:titleStyle/><p:bodyStyle/><p:otherStyle/></p:txStyles></p:sldMaster>");put(z,"ppt/slideMasters/_rels/slideMaster1.xml.rels",rels(rel("layout","slideLayout","../slideLayouts/slideLayout1.xml")+rel("theme","theme","../theme/theme1.xml")));
  put(z,"ppt/slideLayouts/slideLayout1.xml",root("sldLayout")+" type=\"blank\" preserve=\"1\"><p:cSld name=\"Blank\"><p:spTree>"+GROUP+"</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>");put(z,"ppt/slideLayouts/_rels/slideLayout1.xml.rels",rels(rel("master","slideMaster","../slideMasters/slideMaster1.xml")));put(z,"ppt/theme/theme1.xml",theme());
 }}
